                stack, cells = [(r, c)], []
                seen.add((r, c))
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if (r0 <= ny < r1 and c0 <= nx < c1
                                and (ny, nx) not in seen
                                and g[ny][nx] == color):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
                result.append(cells)
        return result

    keys = components(2, 0, mr, 0, mc)
    if not keys:
        return g
    key = max(keys, key=len)
    kr0, kr1 = min(r for r, c in key), max(r for r, c in key) + 1
    kc0, kc1 = min(c for r, c in key), max(c for r, c in key) + 1
    kh, kw = kr1 - kr0, kc1 - kc0

    # Record each template decoration as its color and bounding box relative
    # to the template's 2-object.
    pattern = []
    for color in range(1, 10):
        if color in (2, 4):
            continue
        for obj in components(color, 0, mr, 0, mc):
            r0, r1 = min(r for r, c in obj), max(r for r, c in obj) + 1
            c0, c1 = min(c for r, c in obj), max(c for r, c in obj) + 1
            pattern.append((color, r0 - kr0, r1 - kr0,
                           c0 - kc0, c1 - kc0))

    # For each target 2-object, resize and reflect the decorations.
    regions = [
        (0, mr, mc + 1, W, 1, -1),
        (mr + 1, H, 0, mc, -1, 1),
        (mr + 1, H, mc + 1, W, -1, -1),
    ]
    for r0, r1, c0, c1, sy, sx in regions:
        for obj in components(2, r0, r1, c0, c1):
