            ac0, ac1 = min(c for r, c in obj), max(c for r, c in obj) + 1
            ah, aw = ar1 - ar0, ac1 - ac0
            scale_y, scale_x = ah / kh, aw / kw

            for color, dy0, dy1, dx0, dx1 in pattern:
                if sy > 0:
                    y0 = ar0 + int(dy0 * scale_y)
                    y1 = ar0 + int(dy1 * scale_y)
                else:
                    y0 = ar0 + int((kh - dy1) * scale_y)
                    y1 = ar0 + int((kh - dy0) * scale_y)

                if sx > 0:
                    x0 = ac0 + int(dx0 * scale_x)
                    x1 = ac0 + int(dx1 * scale_x)
                else:
                    x0 = ac0 + int((kw - dx1) * scale_x)
                    x1 = ac0 + int((kw - dx0) * scale_x)

                for y in range(y0, y1):
                    for x in range(x0, x1):
                        if r0 <= y < r1 and c0 <= x < c1 and g[y][x] == 4:
                            g[y][x] = color
    return g
